import{_ as t,o as a,c as s,a4 as r}from"./chunks/framework.ClGzHnIj.js";const m=JSON.parse(`{"title":"Appels d'outils","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/tool-calls.html"}]]},"headers":[],"relativePath":"fr/guide/tool-calls.md","filePath":"fr/guide/tool-calls.md","lastUpdated":1792397420000}`),l={name:"fr/guide/tool-calls.md"};function o(n,e,u,i,d,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="appels-d-outils" tabindex="-1">Appels d&#39;outils <a class="header-anchor" href="#appels-d-outils" aria-label="Permalink to &quot;Appels d&#39;outils&quot;">​</a></h1><p>La page <strong>Appels d&#39;outils</strong> pose une question à un modèle local : sait-il appeler un outil comme un agent en a besoin ? Treize formes de requêtes que les agents envoient toute la journée, notées sur ce que le démon a renvoyé.</p><p><strong>Élément de la barre latérale :</strong> Appels d&#39;outils (sous Carte du GPU) <strong>Route :</strong> <code>/tool-calls</code><strong>Ajouté dans :</strong> v0.8.0 (octobre 2026) <strong>Nécessite :</strong> un modèle qui sait utiliser des outils. Les modèles qui le déclarent sont listés en premier ; n&#39;importe quel modèle de chat peut être coché.</p><h2 id="a-quoi-ca-sert" tabindex="-1">À quoi ça sert ? <a class="header-anchor" href="#a-quoi-ca-sert" aria-label="Permalink to &quot;À quoi ça sert ?&quot;">​</a></h2><p>Les frameworks d&#39;agents vivent ou meurent par les appels d&#39;outils, et les modèles locaux les ratent d&#39;une façon qu&#39;aucun score de benchmark public ne montre : le bon outil avec un argument manquant, un nombre envoyé comme texte, l&#39;appel écrit dans le texte de la réponse où le framework ne le voit jamais, l&#39;appel d&#39;un outil qui n&#39;existe pas, un outil appelé alors qu&#39;il n&#39;en fallait aucun. Chacun casse un agent d&#39;une façon différente.</p><p>La série est née d&#39;un échec mesuré : un modèle de 7,5 milliards de paramètres perdait l&#39;argument obligatoire <code>path</code> dès que l&#39;argument <code>content</code> qu&#39;il écrivait était long. Ce cas figure dans la série sous la forme qui l&#39;a fait échouer.</p><h2 id="les-cas" tabindex="-1">Les cas <a class="header-anchor" href="#les-cas" aria-label="Permalink to &quot;Les cas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cas</th><th>Ce qu&#39;il vérifie</th></tr></thead><tbody><tr><td>Un outil, un argument</td><td>Le plancher.</td></tr><tr><td>Un argument long à côté d&#39;un court</td><td>L&#39;argument court obligatoire survit à un long, avec cinq outils proposés.</td></tr><tr><td>Un argument limité à une liste</td><td>La valeur vient de la liste.</td></tr><tr><td>Un nombre doit être un nombre</td><td>Pas un texte entre guillemets.</td></tr><tr><td>Un argument objet imbriqué</td><td>Des dates et heures dans un objet.</td></tr><tr><td>Deux outils, choisir le bon</td><td>Le bon outil parmi trois.</td></tr><tr><td>Huit outils proposés, choisir le bon</td><td>Le bon outil quand les schémas encombrent l&#39;invite.</td></tr><tr><td>Aucun outil nécessaire</td><td>Une salutation reçoit une réponse, pas un appel.</td></tr><tr><td>Deux appels dans un tour</td><td>Des lectures indépendantes regroupées.</td></tr><tr><td>Répondre après un résultat d&#39;outil</td><td>La seconde moitié de la boucle : utiliser le résultat, ne pas rappeler.</td></tr><tr><td>Un argument avec accents et espaces</td><td>Le chemin survit.</td></tr><tr><td>Laisser de côté un argument facultatif</td><td>Pas de valeur inventée.</td></tr><tr><td>Seulement les outils qui existent</td><td>Pas d&#39;appel à un outil qui n&#39;a jamais été proposé.</td></tr></tbody></table><p>Chaque cas tourne à température 0, sans streaming, par <code>/api/chat</code>, comme un agent l&#39;enverrait.</p><h2 id="lire-les-resultats" tabindex="-1">Lire les résultats <a class="header-anchor" href="#lire-les-resultats" aria-label="Permalink to &quot;Lire les résultats&quot;">​</a></h2><p>Une colonne par modèle avec sa part de cas réussis. Une ligne par cas, avec la raison pour laquelle il compte. Chaque case est une phrase : « l&#39;argument path manque », « a écrit l&#39;appel dans le texte de la réponse », « a appelé search_web alors qu&#39;aucun outil n&#39;était nécessaire ». Cliquez sur une case et la réponse s&#39;ouvre sous la ligne : les appels d&#39;outils émis par le modèle, le texte qu&#39;il a écrit et, quand le démon l&#39;a renvoyé, ce que le modèle a pensé d&#39;abord.</p><p>Un appel d&#39;outil correct n&#39;a pas de texte de réponse. L&#39;appel est la réponse. La page le dit là où c&#39;est le cas.</p><p>La dernière exécution est conservée dans le navigateur ; la relancer la remplace.</p><h2 id="ce-que-la-page-ne-sait-pas" tabindex="-1">Ce que la page ne sait pas <a class="header-anchor" href="#ce-que-la-page-ne-sait-pas" aria-label="Permalink to &quot;Ce que la page ne sait pas&quot;">​</a></h2><p>Si un appel d&#39;outil aurait fonctionné une fois exécuté. Elle juge l&#39;appel lui-même, face au schéma donné au modèle, comme le fait un framework avant d&#39;exécuter quoi que ce soit.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./live.html">En direct</a> montre, tour par tour, les appels d&#39;outils de vos vrais agents.</li><li><a href="./benchmark.html">Benchmark</a> pour les séries de questions et réponses.</li></ul>',17)])])}const h=t(l,[["render",o]]);export{m as __pageData,h as default};
